ITEMS = ["Refunds", "Payments", "Invoices", "Team members", "Roles", "API keys", "Webhooks", "Audit log"]
SORTS = [
    [["Refunds", "Payments", "Invoices"], ["Team members", "Roles", "Audit log"], ["API keys", "Webhooks"]],
    [["Refunds", "Payments", "Invoices"], ["Team members", "Roles"], ["API keys", "Webhooks", "Audit log"]],
    [["Refunds", "Payments", "Invoices", "Audit log"], ["Team members", "Roles"], ["API keys", "Webhooks"]],
    [["Refunds", "Payments", "Invoices"], ["Team members", "Roles"], ["API keys", "Webhooks", "Audit log"]],
    [["Refunds", "Payments"], ["Invoices", "Audit log"], ["Team members", "Roles"], ["API keys", "Webhooks"]],
]

def co_occurrence(sorts):
    co = {}
    for sort in sorts:
        for group in sort:
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    a, b = sorted((group[i], group[j]))
                    co[(a, b)] = co.get((a, b), 0) + 1
    return co

def clusters(co, items, n_participants, threshold=0.6):
    def agree(a, b):
        return co.get((min(a, b), max(a, b)), 0) / n_participants
    pairs = sorted(co.items(), key=lambda kv: (-kv[1], kv[0]))
    placed = {}
    out = []
    for (a, b), count in pairs:
        if count / n_participants < threshold:
            continue
        ina, inb = placed.get(a), placed.get(b)
        if ina is None and inb is None:
            out.append([a, b])
            placed[a] = placed[b] = out[-1]
        elif ina is not None and inb is None:
            if all(agree(b, m) >= threshold for m in ina):
                ina.append(b)
                placed[b] = ina
        elif inb is not None and ina is None:
            if all(agree(a, m) >= threshold for m in inb):
                inb.append(a)
                placed[a] = inb
    return out

co = co_occurrence(SORTS)
out = clusters(co, ITEMS, len(SORTS))
placed = set()
for c in out:
    placed.update(c)
    print(f"cluster: {', '.join(sorted(c))}")
orphans = [i for i in ITEMS if i not in placed]
print(f"orphans: {', '.join(orphans) if orphans else 'none'}")

