    ("order-note field", 800, 0.5, 0.8, 1, "B2B buyers keep emailing delivery notes to support"),
]
BUDGET = 10

def rice(reach, impact, confidence, effort):
    return reach * impact * confidence / effort

def plan(features, budget):
    ranked = sorted(features, key=lambda f: (-rice(f[1], f[2], f[3], f[4]), f[0]))
    goals, non_goals = [], []
    remaining = budget
    for f in ranked:
        if f[4] <= remaining:
            goals.append(f)
            remaining -= f[4]
        else:
            non_goals.append(f)
    return goals, non_goals

goals, non_goals = plan(FEATURES, BUDGET)
goal_names = {f[0] for f in goals}
ranked = sorted(FEATURES, key=lambda f: (-rice(f[1], f[2], f[3], f[4]), f[0]))
for name, reach, impact, conf, effort, risk in ranked:
    tag = "GOAL" if name in goal_names else "NON-GOAL"
    print(f"{name}: rice={rice(reach, impact, conf, effort):.1f} effort={effort} -> {tag}")
print(f"budget-used: {sum(f[4] for f in goals)}/{BUDGET}")
for name, _, _, _, _, risk in ranked:
    if name not in goal_names:
        print(f"non-goal: {name} — accepts: {risk}")

