from collections import deque

TERMINALS = {"success"}

FLOW_A = {
    "list": ["invite-form"],
    "invite-form": ["sending", "list"],
    "sending": ["success", "error"],
    "success": ["list"],
    "error": [],
}
FLOW_B = {
    "list": ["invite-form"],
    "invite-form": ["sending", "list"],
    "sending": ["success", "error"],
    "success": ["list"],
    "error": ["invite-form"],
}

def shortest_path(flow, start, goal):
    seen = {start}
    q = deque([(start, 0)])
    while q:
        node, d = q.popleft()
        if node == goal:
            return d
        for nxt in flow.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return None

def dead_ends(flow):
    return sorted(n for n, outs in flow.items() if not outs and n not in TERMINALS)

for name, flow in (("A", FLOW_A), ("B", FLOW_B)):
    happy = shortest_path(flow, "list", "success")
    ends = dead_ends(flow)
    print(f"{name}: happy-path={happy} dead-ends=[{', '.join(ends)}]")

ra = shortest_path(FLOW_A, "error", "success")
rb = shortest_path(FLOW_B, "error", "success")
fmt = lambda v: "none" if v is None else str(v)
print(f"error-recovery: A={fmt(ra)} B={fmt(rb)}")

