FIELDS = [
    ("name", "required", "Enter your name"),
    ("email", "email", "Enter an email like name@company.com"),
    ("team", "required", "Choose your team"),
    ("tos", "checked", "You must accept the terms"),
]

SUBMITS = [
    {"name": "Ada", "email": "ada@", "team": "", "tos": False},
    {"name": "Ada", "email": "ada@lovelace.dev", "team": "platform", "tos": False},
    {"name": "Ada", "email": "ada@lovelace.dev", "team": "platform", "tos": True},
]

def _passes(rule, value):
    if rule == "required":
        return bool(value) if not isinstance(value, str) else value.strip() != ""
    if rule == "email":
        if not isinstance(value, str) or value.strip() == "":
            return False
        if "@" not in value:
            return False
        domain = value.split("@", 1)[1]
        return "." in domain
    if rule == "checked":
        return value is True
    raise ValueError(f"unknown rule {rule}")

def validate_form(fields, values):
    errors = []
    for name, rule, message in fields:
        if not _passes(rule, values.get(name)):
            errors.append((name, message))
    return errors

requests_sent = 0
for i, values in enumerate(SUBMITS, 1):
    errors = validate_form(FIELDS, values)
    focus = errors[0][0] if errors else "-"
    request = "no" if errors else "yes"
    if not errors:
        requests_sent += 1
    print(f"submit {i}: errors={len(errors)} focus={focus} request={request}")
print(f"requests-sent: {requests_sent}")

