def naive(view):
    if view["loading"]:
        return "loading"
    if view["data"]:
        return "success"
    return "empty"

CASES = [
    ("fresh",        {"loading": True,  "error": None,      "data": None, "elapsed": 0.4}),
    ("slow",         {"loading": True,  "error": None,      "data": None, "elapsed": 13.0}),
    ("failed",       {"loading": False, "error": "TIMEOUT", "data": None, "elapsed": 9.8}),
    ("failed-stale", {"loading": True,  "error": "500",     "data": None, "elapsed": 2.1}),
    ("empty",        {"loading": False, "error": None,      "data": [],   "elapsed": 1.2}),
    ("loaded",       {"loading": False, "error": None,      "data": [1],  "elapsed": 1.0}),
    ("idle",         {"loading": False, "error": None,      "data": None, "elapsed": 0.0}),
]

def resolve(view):
    if view["error"] is not None:
        return "error"
    if view["loading"] and view["elapsed"] >= 12:
        return "error"
    if view["loading"]:
        return "loading"
    if view["data"] == []:
        return "empty"
    if view["data"] is None:
        return "loading"
    return "success"

bugs = 0
for case_id, view in CASES:
    r, n = resolve(view), naive(view)
    tag = "OK" if r == n else "BUG"
    if r != n:
        bugs += 1
    print(f"{case_id}: resolve={r} naive={n} {tag}")
print(f"disagreements: {bugs}/{len(CASES)}")

