    "customer_export_2024-06-02_full_backup_copy.csv",
    "README.md",
]

def naive(name, budget):
    return name if len(name) <= budget else name[: budget - 1] + "…"

def truncate(name, budget):
    if len(name) <= budget:
        return name
    if budget < 12:
        return name[: budget - 1] + "…"
    tail = name[-10:]
    head = name[: budget - 1 - 10]
    return head + "…" + tail

for f in FILES:
    t = truncate(f, BUDGET)
    print(f"{t}  (len={len(t)})")

def collisions(strategy):
    rendered = {}
    for f in FILES:
        rendered.setdefault(strategy(f, BUDGET), set()).add(f)
    return sum(1 for names in rendered.values() if len(names) > 1)

print(f"collisions: naive={collisions(naive)} middle={collisions(truncate)}")

