def weight(w, h, contrast, pos):
    return w * h * contrast * pos / 1000

def computed_order(elements):
    return [name for name, *_ in sorted(elements, key=lambda e: (-weight(*e[1:]), e[0]))]

def inversions(computed, intended):
    out = []
    for i, a in enumerate(intended):
        for b in intended[i + 1:]:
            if computed.index(a) > computed.index(b):
                out.append((a, b))
    return out

