EVENTS = ["click", "click", "click", "reject", "click", "resolve", "timer", "disable", "click", "enable"]

def transition(state, event):
    if event == "disable":
        return ("disabled", "NONE")
    if state == "disabled":
        if event == "enable":
            return ("default", "NONE")
        return ("disabled", "IGNORE")
    if state == "default" and event == "click":
        return ("loading", "FIRE")
    if state == "loading":
        if event == "click":
            return ("loading", "IGNORE")
        if event == "resolve":
            return ("success", "ANNOUNCE_POLITE")
        if event == "reject":
            return ("error", "ANNOUNCE_ASSERTIVE")
    if state == "success" and event == "timer":
        return ("default", "NONE")
    if state == "error" and event == "click":
        return ("loading", "FIRE")
    return (state, "IGNORE")

state = "default"
fired = 0
for event in EVENTS:
    new, action = transition(state, event)
    if action == "FIRE":
        fired += 1
    print(f"{event}: {state} -> {new} [{action}]")
    state = new
print(f"requests-fired: {fired}")

