def _three_sig(x):
    # format to 3 significant figures, strip trailing zeros and dot
    if x >= 100:
        s = str(int(round(x)))
    else:
        digits = 3 - (2 if x >= 10 else 1)
        s = f"{x:.{digits}f}".rstrip("0").rstrip(".")
    return s

def humanize(n):
    if n >= 1_000_000:
        return _three_sig(n / 1_000_000) + "M"
    if n >= 1_000:
        return _three_sig(n / 1_000) + "K"
    return str(round(n))

def classify_delta(prev, cur, noise_pct):
    pct = (cur - prev) / prev * 100
    if abs(pct) < noise_pct:
        return "flat (within noise)"
    if pct > 0:
        return f"up {pct:.1f}%"
    return f"down {abs(pct):.1f}%"

for name, prev, cur, noise in METRICS:
    print(f"{name}: {humanize(cur)} — {classify_delta(prev, cur, noise)}")

