PAIRS = [
    ("error-text", "#ef4444", "#f8fafc", False),
    ("error-text-fixed", "#b91c1c", "#f8fafc", False),
    ("heading", "#ef4444", "#f8fafc", True),
    ("body", "#334155", "#f8fafc", False),
    ("placeholder", "#94a3b8", "#f8fafc", False),
    ("button-label", "#ffffff", "#2563eb", False),
]

def luminance(hex_color):
    h = hex_color.lstrip("#")
    channels = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    lin = [c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4 for c in channels]
    return 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2]

def contrast(fg, bg):
    l1, l2 = luminance(fg), luminance(bg)
    lighter, darker = max(l1, l2), min(l1, l2)
    return (lighter + 0.05) / (darker + 0.05)

def verdict(ratio, large):
    if large:
        if ratio >= 4.5:
            return "AAA"
        if ratio >= 3.0:
            return "AA"
        return "FAIL"
    if ratio >= 7.0:
        return "AAA"
    if ratio >= 4.5:
        return "AA"
    return "FAIL"

failures = 0
for name, fg, bg, large in PAIRS:
    r = contrast(fg, bg)
    v = verdict(r, large)
    if v == "FAIL":
        failures += 1
    print(f"{name}: {r:.2f}:1 {v}")
print(f"failures: {failures}")

