PAGE = ["search", "row-1-delete", "row-2-delete", "row-3-delete", "new-project"]
DIALOG = ["cancel", "confirm"]
KEYS = ["enter", "tab", "tab", "escape", "tab"]

class FocusManager:
    def __init__(self, correct):
        self.correct = correct
        self.focus = "row-3-delete"
        self.dialog_open = False
        self.opener = None

    def press(self, key):
        if key == "enter" and self.focus.endswith("-delete") and not self.dialog_open:
            self.dialog_open = True
            self.opener = self.focus
            if self.correct:
                self.focus = "cancel"
            return self.focus
        if key == "tab":
            if self.dialog_open and self.correct:
                if self.focus in DIALOG:
                    self.focus = DIALOG[(DIALOG.index(self.focus) + 1) % len(DIALOG)]
                else:
                    self.focus = DIALOG[0]
            else:
                self.focus = PAGE[(PAGE.index(self.focus) + 1) % len(PAGE)]
            return self.focus
        if key == "escape" and self.dialog_open:
            if self.correct:
                self.dialog_open = False
                self.focus = self.opener
            return self.focus
        return self.focus

good, bad = FocusManager(True), FocusManager(False)
divergence = None
for i, key in enumerate(KEYS):
    g, b = good.press(key), bad.press(key)
    if divergence is None and g != b:
        divergence = i
    print(f"{key}: correct={g} broken={b}")
print(f"divergence-at: {divergence if divergence is not None else 'none'}")

