def severity(hit_count, n, impact):
    return hit_count / n * impact

def median(xs):
    s = sorted(xs)
    m = len(s) // 2
    return float(s[m]) if len(s) % 2 else (s[m - 1] + s[m]) / 2

def rank(observations, n):
    eligible = [o for o in observations if len(o[1]) > 1]
    return sorted(eligible, key=lambda o: (-severity(len(o[1]), n, o[2]), o[0]))

n = len(SESSIONS)
ranked = rank(OBSERVATIONS, n)
for i, (finding, hits, impact) in enumerate(ranked):
    s = severity(len(hits), n, impact)
    print(f"P{i}: {finding} severity={s:.1f} ({len(hits)}/{n}, impact {impact})")
for finding, hits, impact in OBSERVATIONS:
    if len(hits) == 1:
        print(f"parked: {finding} (n=1)")
