PY_TYPES = {"int": int, "str": str}

def validate(name, props, schema):
    if name not in schema:
        return ["unknown event"]
    problems = []
    for prop, tname in schema[name].items():
        if prop not in props:
            problems.append(f"missing {prop}")
        elif not isinstance(props[prop], PY_TYPES[tname]) or isinstance(props[prop], bool):
            problems.append(f"{prop} must be {tname}")
    return problems

def coverage(events, flow_states):
    seen = {state for _, _, state in events}
    return [s for s in flow_states if s not in seen]

