def root(week_index):
    return TREE["sessions"][week_index] * TREE["start_rate"][week_index] * TREE["completion_rate"][week_index]

def pct_change(metric):
    a, b = TREE[metric]
    return (b - a) / a * 100

def culprit(metrics):
    return max(metrics, key=lambda m: abs(pct_change(m)))

r24, r25 = root(0), root(1)
print(f"root: wk24={r24:.0f} wk25={r25:.0f} change={(r25 - r24) / r24 * 100:+.1f}%")
for d in DRIVERS:
    print(f"{d}: {pct_change(d):+.1f}%")
print(f"driver-culprit: {culprit(DRIVERS)}")
for c in COMPLETION_CHILDREN:
    print(f"{c}: {pct_change(c):+.1f}%")
